/* Original vector character miniatures and adaptation by request. No remote assets. */
'use strict';
const $=id=>document.getElementById(id),{heroes,chapters}=Shiro;
const mentors=[{id:'amado',name:'Amado',hair:'#b52b45',eye:'#fff',dress:'#282633',color:'#9c4c65',role:'Gardien de l’Équilibre',weapon:'Logos',desc:'Épée d’argent droite, quatre rubis alignés. Costume et lunettes blanches mates opaques.'},{id:'rebecca',name:'Rebecca',hair:'#754c3e',eye:'#c68036',dress:'#bd3e49',color:'#bf7444',role:'Artiste de la création',weapon:'Ink Genesis',desc:'Pinceau géant et encre dorée-orange. Veste rouge, t-shirt beige, lunettes fines.'}];
const all=[...heroes,...mentors];
function figure(id){
 const h=all.find(h=>h.id===id),c=h.hair,d=h.dress,ink='#393042',skin='#f5d8c9';
 let back='',front='',clothes='',accessory='',weapon='';
 if(['amanda','amarilys','amavelle','amada'].includes(id))back=`<path d="M37 40 Q20 50 25 ${id==='amavelle'?88:124} L44 111 52 127 67 114 86 124 Q99 65 79 40Z" fill="${c}"/>`;
 if(id==='amarisa')back=`<path d="M37 50Q22 75 32 132M79 50Q94 75 85 132" stroke="${c}" stroke-width="12" fill="none"/><path d="M29 70l8 7-9 8 10 9-8 9 7 9-5 9M87 70l-8 7 9 8-10 9 8 9-7 9 5 9" fill="none" stroke="#46295f" stroke-width="2"/>`;
 if(['amalia','amandine','rebecca'].includes(id))back=`<path d="M75 22Q110 16 96 63L107 86 87 83Q85 55 72 52Z" fill="${c}"/>${id==='amalia'?`<circle cx="74" cy="23" r="16" fill="${c}"/><path d="M62 24l24-7" stroke="#c3b9ee" stroke-width="3"/>`:''}`;
 const boots=`<path d="M44 123l-2 30-7 7q1 5 15 1l5-37M65 123l3 30-2 8q7 4 16-1l-6-8-1-28" fill="${id==='amada'?'#315742':'#302b3c'}"/>`;
 clothes=`<path d="M44 70Q58 65 73 70L86 127Q59 139 31 127Z" fill="${d}"/><path d="M53 83L46 124M65 83l8 43" fill="none" stroke="#fff" opacity=".12" stroke-width="3"/>`;
 if(id==='amanda')clothes=`<path d="M44 70h29l13 52-32 10-22-15Z" fill="${d}"/><path d="M43 69l-8 29 16-3 5-26M67 69l8 28 9-3-10-24" fill="#292735"/><path d="M51 102l21-1" stroke="#dda0ac"/>`;
 if(id==='amandine')clothes=`<path d="M43 70h31l8 39-12 4-9-12-10 12-15-5Z" fill="#262a36"/><path d="M44 109l-2 25 13 1 6-27 7 27 13-1-7-26" fill="#303340"/><g stroke="#f3aa36" fill="none"><circle cx="59" cy="86" r="8"/><path d="M59 72v28M45 86h28M49 76l20 20M69 76L49 96M42 98l7 8M75 98l-7 8"/></g>`;
 if(id==='amada')clothes=`<path d="M44 70Q57 77 73 70L84 108 77 134 62 122 49 135 32 115Z" fill="#448c66"/><path d="M45 76Q36 100 49 123Q60 106 59 82Q64 106 77 125Q83 100 71 75" fill="#68a87c"/><path d="M58 80v41" stroke="#b5db9a" fill="none"/>`;
 if(id==='amalia')clothes+=`<g fill="#c9d6ff"><circle cx="48" cy="92" r="1.4"/><circle cx="68" cy="101" r="1.5"/><circle cx="55" cy="116" r="1.3"/><path d="M61 85l2 4-2 4-2-4ZM72 117l2 3-2 3-2-3Z"/></g><path d="M43 100L71 118 68 101 48 92" fill="none" stroke="#8799d6" stroke-width=".6"/>`;
 if(id==='amarilys')clothes=`<path d="M44 70h29l14 67-20-8-7-29-8 29-24 8Z" fill="#252331"/><path d="M43 92h30l5 18H38Z" fill="#393443"/><path d="M59 71v27" stroke="#686172"/>`;
 if(id==='amavelle')clothes=`<path d="M37 72L21 131 57 121 94 132 80 72Z" fill="#9274a0" opacity=".18"/>`+clothes+`<path d="M40 75l9 4 9-6 11 6 10-4M40 124q18 11 40 0" fill="none" stroke="#ba9a59" stroke-width="2"/><path d="M54 77l5 8 5-8" fill="#b59858"/>`;
 if(id==='amado')clothes=`<path d="M43 70h31l6 39-15 3-6-8-8 8-15-3Z" fill="#292834"/><path d="M48 70l11 22 10-22" fill="#e8e5ed"/><path d="M58 72l-3 7 4 17 5-17-4-7" fill="#8e3755"/><path d="M42 110l-1 27h13l5-26 8 26h12l-5-27" fill="#292834"/>`;
 if(id==='rebecca')clothes=`<path d="M44 70h30l6 39H37Z" fill="#e9d5b6"/><path d="M43 69L35 111h16l3-40M66 71l4 40h15L76 69" fill="#b63847"/><path d="M40 110h38l1 24H65l-7-21-6 21H38Z" fill="#333040"/>`;
 const arms=`<path d="M42 76L31 91l-3 16M75 76l10 15 8 8" stroke="${id==='amada'?'#4d8a64':id==='rebecca'?'#b63847':d}" stroke-width="10" fill="none" stroke-linecap="round"/><path d="M28 104l-1 6M92 99l3 4" stroke="${['amanda','amandine','amarisa','amado'].includes(id)?'#2a2635':skin}" stroke-width="7" stroke-linecap="round"/>`;
 const hair=`<path d="M35 45Q29 19 57 17Q86 15 85 47L76 36 70 43 61 30 52 42 47 34 36 49Z" fill="${c}"/><path d="M36 37l-3 28 9-13M80 36l5 27-8-10" fill="${c}"/><path d="M41 29Q56 20 73 27" fill="none" stroke="#fff" opacity=".25" stroke-width="3"/>`;
 if(id==='amarisa')accessory=`<path d="M23 29L48 4l16 5 15 22Z" fill="#4b2a6b"/><ellipse cx="58" cy="32" rx="43" ry="8" fill="#68408a"/><path d="M37 25q20 9 42 0" stroke="#b39bd0" stroke-width="3" fill="none"/>`;
 if(id==='amavelle')accessory=`<g fill="#27222f"><circle cx="79" cy="33" r="5"/><circle cx="86" cy="38" r="5"/><circle cx="82" cy="45" r="5"/><circle cx="75" cy="41" r="5"/></g><circle cx="80" cy="39" r="3" fill="#b89d64"/>`;
 const eyes=id==='amado'?`<path d="M37 44h20v12H37zM62 44h20v12H62z" fill="#fff" stroke="#1d1c23" stroke-width="3"/><path d="M57 48h5" stroke="#1d1c23" stroke-width="3"/>`:`<path d="M40 47q7-4 13 1l-1 7q-6 4-11-2ZM65 48q7-5 13-1l-1 6q-5 6-11 2Z" fill="#fff"/><ellipse cx="47" cy="51" rx="3" ry="5" fill="${h.eye}"/><ellipse cx="71" cy="51" rx="3" ry="5" fill="${h.eye}"/><path d="M39 47q7-4 15 1M64 48q7-5 15-1" stroke="${ink}" stroke-width="2" fill="none"/><circle cx="48" cy="49" r="1" fill="white"/><circle cx="72" cy="49" r="1" fill="white"/>`;
 if(id==='rebecca')front=`<rect x="38" y="44" width="18" height="13" rx="4" fill="none" stroke="#594a51"/><rect x="63" y="44" width="18" height="13" rx="4" fill="none" stroke="#594a51"/><path d="M56 48h7" stroke="#594a51"/>`;
 if(id==='amanda')weapon=`<path d="M99 135V23" stroke="#a32b50" stroke-width="4"/><path d="M99 3l-8 23 8 13 8-13Z" fill="#dc5476" stroke="#8e2848"/><path d="M99 6v28" stroke="#f5b6c8"/>`;
 if(id==='amandine')weapon=`<path d="M95 46q34 37 0 73" fill="none" stroke="#292837" stroke-width="6"/><path d="M95 46q28 36 0 73" fill="none" stroke="#cda443" stroke-width="2"/><path d="M95 46l-9 36 9 37M83 82h34" stroke="#e9b83e" fill="none"/><path d="M119 82l-9-5v10Z" fill="#e9b83e"/>`;
 if(id==='amada')weapon=`<path d="M94 102Q115 73 98 65T104 27M94 102q-24 38 11 35" fill="none" stroke="#319d68" stroke-width="4"/><path d="M101 80l9-3-7 9M99 58l-8-6 8 1M98 123l-7 5 9 2" fill="#2e8056"/>`;
 if(id==='amalia')weapon=`<path d="M97 134V40" stroke="#354b89" stroke-width="5"/><circle cx="97" cy="29" r="12" fill="none" stroke="#899bdb" stroke-width="3"/><path d="M97 14l4 14-4 15-4-15Z" fill="#88b7eb"/><ellipse cx="97" cy="29" rx="18" ry="5" fill="none" stroke="#b2bde0"/>`;
 if(id==='amarilys'||id==='amado')weapon=`<path d="M97 98V21l-5-12-5 12v77Z" fill="#d6dce7" stroke="#a1a8bb"/><path d="M92 15v78" stroke="white"/><path d="M83 98h18M92 98v20" stroke="#272433" stroke-width="5"/>${id==='amado'?[33,47,61,75].map(y=>`<path d="M92 ${y-4}l3 4-3 4-3-4Z" fill="#b82b4b"/>`).join(''):''}`;
 if(id==='amarisa')weapon=`<path d="M79 83l17-4 19 7-3 25-17-6-18 3Z" fill="#47265f" stroke="#ac85cc" stroke-width="2"/><path d="M82 86l14-4 15 6-2 19-14-5-15 3Z" fill="#d6bee9"/><path d="M96 83l-1 19M100 90l7 3M100 96l6 3M84 92l7-2" stroke="#79549e" fill="none"/><text x="99" y="70" font-size="16" fill="#a076c2">Σ</text>`;
 if(id==='amavelle')weapon=`<path d="M95 125V62" stroke="#4c3d5c" stroke-width="6"/><path d="M77 42l33-4 8 12-3 27-35 4-7-12Z" fill="#292331" stroke="#645075" stroke-width="2"/><path d="M80 47l28-3 5 8-29 4Z" fill="#554061"/><path d="M87 60l10 5-8 5" stroke="#92719d" fill="none"/>`;
 if(id==='rebecca')weapon=`<path d="M96 132V57" stroke="#6b3b2d" stroke-width="7"/><path d="M89 56h14V43H89Z" fill="#be9250"/><path d="M89 43Q80 23 96 5Q109 26 103 43Z" fill="#e19b3d"/><path d="M99 10q21 8 9 22" fill="none" stroke="#eab855" opacity=".7" stroke-width="4"/>`;
 return `<svg viewBox="0 0 120 170" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><g stroke-linejoin="round"><ellipse cx="60" cy="163" rx="31" ry="5" fill="#302239" opacity=".12"/>${back}${boots}${clothes}${arms}<path d="M53 61v12q6 7 13 0V61" fill="${skin}"/><path d="M35 37Q38 19 59 21Q83 22 84 40L80 57Q71 70 59 73Q45 69 37 57Z" fill="${skin}" stroke="#dbb7ac" stroke-width=".7"/>${eyes}<path d="M57 61q3 2 6 0" stroke="#ac6d71" fill="none" stroke-width="1"/>${hair}${front}${accessory}${weapon}</g></svg>`;
}
const KEY='shirogane-resonances-v1';let saved={unlocked:0,team:['amanda','amandine','amada','amalia'],wins:[]},s=null,stage=0,selected='amanda',mode='move',busy=false,soundOn=false,audioCtx=null;
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw&&Number.isInteger(raw.unlocked)&&raw.unlocked>=0&&raw.unlocked<=2&&Array.isArray(raw.team)&&raw.team.length===4&&new Set(raw.team).size===4&&raw.team.every(x=>heroes.some(h=>h.id===x))){saved={...saved,...raw};stage=saved.unlocked;}}catch(e){}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));$('saveText').textContent='Progression sauvegardée';}catch(e){$('saveText').textContent='Sauvegarde indisponible';}}
function sound(freq=440){if(!soundOn)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.setValueAtTime(freq,audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.65,audioCtx.currentTime+.22);g.gain.setValueAtTime(.065,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.32);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.33);}catch(e){}}
let toastTimer;function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3200);}
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function modal(title,body,foot=''){const m=$('modal');$('modalContent').innerHTML=`<div class="modal-head"><div><div class="section-label">SHIROGANE UNIVERSE</div><h2>${title}</h2></div><button class="close" id="closeModal" aria-label="Fermer">×</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;$('closeModal').onclick=()=>m.close();if(!m.open)m.showModal();}
function close(){ $('modal').close(); }
function point(x,y){return {x:470+(x-y)*52,y:228+(x+y)*25};}
function draw(){
 let state=s||Shiro.create(stage,saved.team),active=state.allies.find(h=>h.id===selected)||state.allies[0];let moves=s&&mode==='move'&&active.ap?Shiro.reachable(s,active):[];
 let out=`<defs><radialGradient id="halo"><stop stop-color="#c7a8e9" stop-opacity=".25"/><stop offset="1" stop-color="#e6dbef" stop-opacity="0"/></radialGradient><linearGradient id="crystal" x2=".8" y2="1"><stop stop-color="#b193ce"/><stop offset=".5" stop-color="#68507f"/><stop offset="1" stop-color="#352740"/></linearGradient><filter id="glow"><feGaussianBlur stdDeviation="6"/></filter></defs><ellipse cx="470" cy="220" rx="330" ry="180" fill="url(#halo)"/><g fill="none" stroke="#c4b1d5" opacity=".42"><ellipse cx="470" cy="165" rx="70" ry="102"/><ellipse cx="470" cy="165" rx="76" ry="110"/><path d="M470 53v-12M470 277v12M387 165h-12M553 165h12"/><g class="portal-ring"><circle cx="470" cy="165" r="130" stroke-dasharray="1 18"/><path d="M470 28l7 11-7 11-7-11ZM470 280l7 11-7 11-7-11Z"/></g><g class="portal-ring reverse"><circle cx="470" cy="165" r="150" stroke-dasharray="55 80"/></g></g><path d="M465 72l8 52-13 42 17 22-6 58" fill="none" stroke="#9a70ba" stroke-width="3" opacity=".45"/><path d="M465 72l8 52-13 42 17 22-6 58" fill="none" stroke="#b184d2" stroke-width="14" opacity=".35" filter="url(#glow)"/>`;
 for(let x=0;x<7;x++)for(let y=0;y<7;y++){let p=point(x,y),valid=moves.some(a=>a.x===x&&a.y===y),current=s&&active.x===x&&active.y===y;out+=`<path class="tile" data-x="${x}" data-y="${y}" role="button" tabindex="${valid?0:-1}" aria-label="Case ${x+1}, ${y+1}${valid?', déplacement possible':''}" d="M${p.x} ${p.y-25}l52 25-52 25-52-25Z" fill="${current?'#dac6e8':valid?'#eee3f5':(x+y)%2?'#f9f6fc':'#f1edf6'}" stroke="${valid?'#c9b4dd':'#e0d7e9'}" stroke-width="1"/>${valid?`<circle cx="${p.x}" cy="${p.y}" r="2.5" fill="#b595cc"/>`:''}`;}
 out+=`<path d="M158 378l-24 12 17 20-27 8M775 367l22 12-10 27 24 11M443 529l14 15-5 21" stroke="#b9a6ca" stroke-width="1.5" fill="none" opacity=".5"/>`;
 const units=[...state.allies.map(h=>({...h,ally:true})),...state.enemies].sort((a,b)=>(a.x+a.y)-(b.x+b.y));
 for(const u of units){if(u.hp<=0)continue;let p=point(u.x,u.y),aim=s&&!u.ally&&['attack','skill'].includes(mode)&&Shiro.dist(active,u)<=(mode==='attack'?active.range:active.id==='amandine'?6:2);let label=u.ally?`${u.name}, ${u.hp} PV, ${u.ap} actions`:`${u.name}, ${u.hp} PV. ${Shiro.intent(state,u)}`;out+=`<g class="unit" data-unit="${u.id}" role="button" tabindex="0" aria-label="${label}" transform="translate(${p.x},${p.y})"><title>${label}</title><ellipse rx="28" ry="12" fill="${u.ally?u.color:'#705488'}" opacity=".15"/>${s&&u.id===selected?`<ellipse rx="32" ry="15" fill="none" stroke="${u.color}" stroke-width="2" stroke-dasharray="6 3"/>`:''}${aim?'<ellipse rx="33" ry="16" fill="none" stroke="#c85f86" stroke-width="2"/>':''}`;
 if(u.ally)out+=`<g class="figure"><svg x="-39" y="-112" width="78" height="115" viewBox="0 0 120 170">${figure(u.id).replace(/<svg[^>]*>|<\/svg>/g,'')}</svg></g>`;
 else {const boss=u.name==='Noyau',anchor=u.name==='Ancrage';out+=`<g class="enemy-core" transform="translate(0,-45)">${boss?'<circle cy="-12" r="36" fill="none" stroke="#84629f" stroke-width="2" stroke-dasharray="12 7"/><path d="M-33-26l-17-18 9 36-12 25 22-9M33-26l17-18-9 36 12 25-22-9" fill="#574265"/>':''}<path d="M0 ${boss?-58:-40}L${anchor?17:26} -7 15 20 0 33-16 20-${anchor?17:26}-7Z" fill="url(#crystal)" stroke="#a184b6" stroke-width="1.5"/><path d="M0 ${boss?-58:-40}L-7-3 0 33 8-3Z" fill="#b89bd0" opacity=".5"/><path d="M-14-2l11 5M14-2L3 3" stroke="#e8c8f3" stroke-width="3"/>${boss?'<path d="M-4 11l4-3 4 3-4 5Z" fill="#ebc1f8"/>':''}</g>`;}
 out+=`<rect x="-24" y="8" width="48" height="4" rx="2" fill="#d9cfe0"/><rect x="-24" y="8" width="${48*u.hp/u.maxhp}" height="4" rx="2" fill="${u.ally?u.color:'#86649d'}"/><text y="26" text-anchor="middle" font-family="Arial" font-size="9" fill="#786882">${u.name}${u.shield?' ◇'+u.shield:''}${u.silence?' ∅':''}${u.root?' ⌁':''}</text></g>`;
 }
 if(s)for(const ev of s.events||[]){let u=[...s.allies,...s.enemies].find(u=>u.id===ev.id);if(u){let p=point(u.x,u.y);out+=`<text x="${p.x}" y="${p.y-115}" text-anchor="middle" class="float-label">${ev.text}</text>`;}}
 $('arena').innerHTML=out;
 $('arena').querySelectorAll('.tile').forEach(el=>{const go=()=>{if(!s)return;perform('move',{x:Number(el.dataset.x),y:Number(el.dataset.y)});};el.onclick=go;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}};});
 $('arena').querySelectorAll('.unit').forEach(el=>{const go=()=>{if(!s)return;let id=el.dataset.unit;if(s.allies.some(h=>h.id===id)){selected=id;mode='move';render();}else if(mode==='attack'||mode==='skill')perform(mode,id);else{const e=s.enemies.find(e=>e.id===id);toast(e.name+' · '+Shiro.intent(s,e)+'. Sélectionnez Frapper ou votre technique.');}};el.onclick=go;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}};});
}
function render(){
 $('chapters').innerHTML=chapters.map((c,i)=>`<button class="chapter ${stage===i?'current':''}" data-stage="${i}" ${i>saved.unlocked?'disabled':''}><span class="num">${saved.wins.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span><strong>${c.name}</strong><small>${i>saved.unlocked?'VERROUILLÉ':saved.wins.includes(i)?'COHÉRENCE RESTAURÉE':i===stage?'EXPÉDITION ACTIVE':'DISPONIBLE'}</small></span></button>`).join('');
 $('chapters').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(s&&s.status==='playing'){toast('Terminez cette rencontre ou quittez via Expédition.');return;}stage=Number(b.dataset.stage);s=null;render();});
 $('missionInfo').innerHTML=`<div class="section-label">${s?'LOI DU DOMAINE':'VOTRE OBJECTIF'}</div><h3>${s?'Comprendre pour agir.':'Rétablir l’équilibre.'}</h3><p>${s?chapters[stage].rule:chapters[stage].objective+' Une mission tactique dans le vide entre les mondes.'}</p>`;
 $('turnBadge').textContent=s?(busy?'LES ANOMALIES AGISSENT':`TOUR ${s.round} · À VOUS DE JOUER`):'EXPÉDITION EN ATTENTE';
 $('arenaHint').textContent=!s?'Composez votre équipe, puis franchissez le seuil.':mode==='move'?'Touchez une case teintée pour vous déplacer.':mode==='attack'?'Touchez un ennemi à portée.':mode==='skill'?'Choisissez la cible de votre technique.':'Préparez votre prochaine action.';
 let party=s?s.allies:saved.team.map(id=>({...heroes.find(h=>h.id===id),maxhp:heroes.find(h=>h.id===id).hp,ap:2}));
 $('party').innerHTML=party.map(h=>`<button class="hero-card ${s&&selected===h.id?'chosen':''} ${h.hp<=0?'knocked':''}" style="--c:${h.color}" data-hero="${h.id}" aria-label="Sélectionner ${h.name}"><div class="portrait">${figure(h.id)}</div><div class="card-body"><strong>${h.name}</strong><small>${h.role}</small><div class="hp-line"><i style="width:${h.hp/h.maxhp*100}%"></i></div><div class="card-stats"><span>${h.hp} / ${h.maxhp} PV${h.shield?' · ◇'+h.shield:''}</span><span class="ap">${'●'.repeat(h.hp>0?h.ap:0)}${'○'.repeat(h.hp>0?2-h.ap:2)}</span></div></div></button>`).join('');
 $('party').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(s){selected=b.dataset.hero;mode='move';render();}else codex(b.dataset.hero);});
 if(!s){$('command').innerHTML=`<div class="command-info"><small>CHAPITRE ${String(stage+1).padStart(2,'0')}</small><strong>${chapters[stage].name}</strong></div><button class="primary" id="start">Entrer dans l’Intermonde <span>↗</span></button>`;$('start').onclick=start;}
 else {
  let h=s.allies.find(h=>h.id===selected);if(!h||h.hp<=0){h=s.allies.find(h=>h.hp>0)||s.allies[0];selected=h.id;}
  $('command').innerHTML=`<div class="command-info"><small>${h.weapon.toUpperCase()} · ${h.ap} PA</small><strong>${h.name}</strong></div><div class="actions"><button class="action ${mode==='move'?'selected':''}" id="move" ${busy||h.ap<1?'disabled':''}>Déplacer<small>1 PA · ${h.move} cases</small></button><button class="action ${mode==='attack'?'selected':''}" id="attack" ${busy||h.ap<1?'disabled':''}>Frapper<small>1 PA · portée ${h.range}</small></button><button class="action ${mode==='skill'?'selected':''}" id="skill" title="${h.desc}" ${busy||h.ap<2?'disabled':''}>${h.skill}<small>2 PA · technique</small></button><button class="action" id="guard" ${busy||h.ap<1?'disabled':''}>Garde<small>1 PA · +14 ◇</small></button><button class="action end" id="end" ${busy?'disabled':''}>Fin du tour<small>Restaurer les PA →</small></button></div>`;
  $('move').onclick=()=>{mode='move';render();};$('attack').onclick=()=>{mode='attack';render();};$('skill').onclick=()=>{if(['amada','amalia','amarisa','amavelle'].includes(selected))perform('skill');else{mode='skill';toast(h.desc);render();}};$('guard').onclick=()=>perform('guard');$('end').onclick=endTurn;
 }
 const charge=s?s.charge:0;$('chargeLabel').textContent=charge+' %';$('chargeBar').style.width=charge+'%';$('resonate').disabled=!s||charge<100||busy||s.status!=='playing';$('teamBtn').disabled=!!s&&s.status==='playing';$('log').innerHTML=(s?s.log.slice(-2):['Le vide ne devrait rien abriter. Pourtant, quelque chose s’y forme…']).map(t=>`<div>${escapeHTML(t)}</div>`).join('');draw();
}
function perform(kind,target){if(!s||busy)return;const error=Shiro.act(s,selected,kind,target);if(error){toast(error);return;}sound(kind==='resonance'?660:kind==='skill'?550:330);if(kind==='move')mode='attack';render();if(s.status!=='playing')finish();else if(s.allies.every(a=>a.hp<=0||a.ap===0))toast('Toutes vos actions sont utilisées. Terminez le tour.');}
function endTurn(){if(!s||busy||s.status!=='playing')return;busy=true;render();setTimeout(()=>{Shiro.end(s);busy=false;mode='move';sound(160);render();if(s.status!=='playing')finish();},650);}
function start(){
 const lines=stage===0?[['amado','Une anomalie dans l’Intermonde… Ce lieu devrait rester vide. Observez ses mouvements avant de frapper.'],['rebecca','Vos essences se complètent. Restez proches de vos partenaires : vos actions nourriront une Résonance collective.'],['amandine','Donc on entre, on comprend le problème, et on le règle avec style ? Ça me va.']]:stage===1?[['amado','Cet Écho retient vos gestes. Si la même sœur le frappe deux fois de suite, il s’adapte. Changez de rythme.'],['amarisa','Alterner les attaquantes. Une contrainte simple, une réponse collective.']]:[['rebecca','Le Noyau est relié à deux Ancrages. Tant qu’ils tiennent, vos coups perdent presque toute leur force.'],['amavelle','Alors nous allons défaire ces liens. Ensemble.']];
 dialogue(lines,()=>{s=Shiro.create(stage,saved.team);selected=s.allies[0].id;mode='move';render();toast('Chaque sœur dispose de 2 PA. Déplacez-la, puis frappez une cible à portée.');});
}
function dialogue(lines,done,i=0){let [id,line]=lines[i],h=all.find(h=>h.id===id);modal('',`<div class="dialogue">${figure(id)}<div><small>${h.role.toUpperCase()}</small><h2>${h.name}</h2><p>${line}</p><button class="primary" id="nextLine">${i===lines.length-1?'Franchir le seuil':'Continuer'} →</button><p style="font:9px Arial;color:#aaa">${i+1} / ${lines.length}</p></div></div>`);$('nextLine').onclick=()=>{sound(500);if(i<lines.length-1)dialogue(lines,done,i+1);else{close();done();}};}
function finish(){const win=s.status==='won';if(win){if(!saved.wins.includes(stage))saved.wins.push(stage);saved.unlocked=Math.max(saved.unlocked,Math.min(2,stage+1));persist();}setTimeout(()=>{modal('',`<div class="result"><div class="big-sigil">${win?'✧':'◇'}</div><div class="section-label" style="justify-content:center">${win?'MISSION ACCOMPLIE':'LA COHÉRENCE A CÉDÉ'}</div><h2>${win?(stage===2?'Sept essences. Un même souffle.':'L’équilibre retrouvé.'):'Les liens peuvent se renouer.'}</h2><p>${win?(stage===2?'La faille se referme. La résidence vous attend.<br>Vous avez terminé les trois rencontres de cette démo.':'L’Intermonde retrouve son silence. Une nouvelle rencontre vous attend.'):'Essayez une autre formation, protégez vos gardiennes et exploitez les techniques de soutien.'}</p><div class="stats"><div><strong>${s.round}</strong><small>TOURS</small></div><div><strong>${s.allies.filter(h=>h.hp>0).length} / 4</strong><small>GARDIENNES DEBOUT</small></div></div></div>`,`<button class="secondary" id="returnHub">Retour à l’expédition</button><button class="primary" id="nextBattle">${win&&stage<2?'Rencontre suivante →':'Rejouer la rencontre'}</button>`);$('returnHub').onclick=()=>{close();s=null;render();};$('nextBattle').onclick=()=>{close();if(win&&stage<2)stage++;s=null;render();start();};render();},450);}
function teamPicker(){if(s&&s.status==='playing')return;let picks=[...saved.team];const refresh=()=>{modal('Choisir les gardiennes',`<p>Quatre sœurs pour cette expédition. Les duos Amanda–Amandine, Amada–Amalia et Amarilys–Amarisa gagnent davantage de Résonance à proximité. Amavelle peut rejoindre toute formation.</p><div class="pick-grid">${heroes.map(h=>`<button class="pick ${picks.includes(h.id)?'picked':''}" style="--c:${h.color}" data-pick="${h.id}" aria-pressed="${picks.includes(h.id)}"><span class="checkmark">${picks.includes(h.id)?'●':'○'}</span>${figure(h.id)}<strong>${h.name}</strong><small>${h.weapon}</small></button>`).join('')}</div>`,`<button class="primary" id="confirmTeam" ${picks.length!==4?'disabled':''}>Confirmer · ${picks.length} / 4</button>`);$('modal').querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{let id=b.dataset.pick;if(picks.includes(id))picks=picks.filter(x=>x!==id);else if(picks.length<4)picks.push(id);else{toast('Retirez une sœur avant d’en choisir une autre.');return;}refresh();});$('confirmTeam').onclick=()=>{saved.team=picks;persist();s=null;selected=picks[0];close();render();};};refresh();}
function codex(id){let list=id?all.filter(h=>h.id===id):all;modal(id?list[0].name:'Les visages de la Conscience',`<p>Les sept héroïnes sont jouables. Amado et Rebecca vous accompagnent dans les dialogues. Miniatures vectorielles stylisées d’après vos descriptions.</p><div class="codex-grid" ${id?'style="grid-template-columns:1fr"':''}>${list.map(h=>`<article class="codex-card" style="--c:${h.color}">${figure(h.id)}<h3>${h.name}</h3><p>${h.role}</p><strong>${h.weapon}${h.skill?' · '+h.skill:''}</strong><p>${h.desc}</p>${h.range?`<p>PV ${h.hp} · attaque ${h.atk}<br>Portée ${h.range} · déplacement ${h.move}</p>`:''}</article>`).join('')}</div>`);}
function help(){modal('Chaque action compte.',`<ol class="help-list"><li><b>Choisissez quatre gardiennes</b> avec « Modifier l’équipe », puis entrez dans l’Intermonde.</li><li><b>Sélectionnez une sœur</b> sur le terrain ou dans les cartes. Elle reçoit 2 points d’action à chaque tour.</li><li><b>Déplacez-vous</b> sur une case teintée (1 PA), puis choisissez « Frapper » et touchez un ennemi à portée (1 PA). Les distances se comptent par les côtés des cases.</li><li><b>Une technique coûte 2 PA.</b> Les techniques de soutien ou de zone s’activent immédiatement. Les autres demandent une cible.</li><li><b>Restez proches de votre duo</b> (3 cases au plus) pour charger plus vite la Résonance. À 100 %, libérez-la : dégâts collectifs et soin, sans coût en PA.</li><li><b>Terminez le tour</b> pour laisser agir les anomalies et récupérer vos PA. La Garde absorbe 14 dégâts.</li><li><b>Lisez la loi du domaine.</b> Alternez les attaques contre l’Écho. Détruisez les Ancrages avant le Noyau.</li></ol><p>Clavier : <span class="key">1–4</span> sélectionner une sœur, <span class="key">D</span> déplacer, <span class="key">A</span> frapper, <span class="key">S</span> technique, <span class="key">G</span> garde, <span class="key">E</span> fin du tour. Les cases sont aussi accessibles par Tab puis Entrée.</p><p>La progression entre les missions est sauvegardée sur cet appareil. Une rencontre en cours recommence si vous rechargez la page.</p>`);}
function sources(){modal('Une adaptation de ton univers',`<p>Cette démo est une mission originale d’entraînement située après l’arrivée d’Amavelle. Elle ne prétend pas reproduire mot pour mot un chapitre.</p><div class="source-list"><b>Souffle 1–4 · chapitre 12, pages PDF 67–72</b><br>Intermonde : espace neutre entre les mondes et la Terre, normalement vide. Duos de Résonance établis dans le texte.<br><br><b>Souffle 1–4 · chapitres 73–77</b><br>Les essences humaines des sept Ama Girls et leur complémentarité.<br><br><b>Souffle 9–12 · chapitres 665–666</b><br>Coordination des armes et synchronisation physique et conceptuelle.<br><br><b>Descriptions fournies par Amado · 14 octobre 2026</b><br>Tenues, coiffures et artefacts des neuf personnages.</div><p>La grille est une aide de lecture tactique, pas un sol naturel de l’Intermonde. Les chiffres, les trois rencontres, les dialogues et les effets simplifiés sont des adaptations de gameplay. La blancheur sans horizon et les fissures rendent le lieu jouable sans le transformer en paysage terrestre.</p>`);}
function hub(){if(!s||s.status!=='playing'){s=null;render();return;}modal('Quitter la rencontre ?',`<p>Votre progression entre les missions sera conservée. Cette rencontre recommencera depuis le début.</p>`,`<button class="secondary" id="stay">Continuer le combat</button><button class="primary" id="leave">Retour à l’expédition</button>`);$('stay').onclick=close;$('leave').onclick=()=>{close();s=null;render();};}
$('home').onclick=e=>{e.preventDefault();hub();};$('hubNav').onclick=hub;$('codexNav').onclick=()=>codex();$('helpNav').onclick=help;$('sourceBtn').onclick=sources;$('teamBtn').onclick=teamPicker;$('resonate').onclick=()=>perform('resonance');$('sound').onclick=()=>{soundOn=!soundOn;$('sound').innerHTML=`♫ <span>Son ${soundOn?'activé':'désactivé'}</span>`;$('sound').setAttribute('aria-label',soundOn?'Désactiver le son':'Activer le son');sound(600);};
document.addEventListener('keydown',e=>{if($('modal').open||!s||busy)return;if(e.key>='1'&&e.key<='4'){selected=s.allies[Number(e.key)-1].id;mode='move';render();}const keys={d:'move',a:'attack',s:'skill',g:'guard',e:'end'};const button=$(keys[e.key.toLowerCase()]);if(button&&!button.disabled){e.preventDefault();button.click();}});
render();
